#!/usr/bin/env python3"""Скрипт для обновления категорий существующих агентов"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from sqlmodel import Session, selectfrom models.agent import Agentfrom core.database import enginedef update_agent_categories():    """Обновить категории для существующих агентов"""    with Session(engine) as session:        # Получаем всех агентов        agents = session.exec(select(Agent)).all()        print(f"Найдено {len(agents)} агентов для обновления:")                updated_count = 0                for agent in agents:            print(f"\n🔍 Обрабатываем агента: {agent.name} (ID: {agent.id})")            print(f"   Текущая категория: {agent.category}")                        # Определяем категорию на основе имени агента            name_lower = agent.name.lower()                        if any(name in name_lower for name in ["путин", "платон", "гарри", "поттер", "ницше", "дарт", "вейдер"]):                new_category = "chats"            elif "калькулятор" in name_lower:                new_category = "tools"            elif "deepseek" in name_lower or "assistant" in name_lower:                new_category = "models"            else:                new_category = "chats"  # По умолчанию для персонажей                        if agent.category != new_category:                agent.category = new_category                session.add(agent)                updated_count += 1                print(f"   ✅ Обновлено: {agent.category} → {new_category}")            else:                print(f"   ⏭️  Категория уже правильная: {agent.category}")                if updated_count > 0:            session.commit()            print(f"\n🎉 Обновлено {updated_count} агентов!")        else:            print(f"\n✨ Все категории уже корректны!")                # Показываем финальное состояние        print(f"\n📊 Финальное состояние агентов:")        agents = session.exec(select(Agent)).all()        for agent in agents:            print(f"  - {agent.name} (ID: {agent.id}, категория: {agent.category})")if __name__ == "__main__":    update_agent_categories()